// Everything both pages share: brand marks, the ported card primitives
// (BlobCard, Avatar, Reactions, badges) and the PostCard color system.
// Page-specific demo content (the feed, profile, event card) stays in
// about.jsx; the coming-soon hero stays in home.jsx.

// `colors` is aliased to C because the ported mobile components use that
// short name throughout.
export const C = colors;

// Reveal-on-scroll: a quick fade only. Runs once per element.
export function useReveal() {
  useEffect(() => {
    const els = document.querySelectorAll("[data-reveal]");
    if (!("IntersectionObserver" in window)) {
      els.forEach((el) => el.classList.add("in-view"));
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            e.target.classList.add("in-view");
            io.unobserve(e.target);
          }
        });
      },
      { threshold: 0.12 },
    );
    els.forEach((el) => io.observe(el));
    return () => io.disconnect();
  }, []);
}

// Mirrors the app's timeAgo(post.created_at) utility (see
// lib/utils/timeAgo.js): same three buckets, same "Xh ago" / "Xd ago"
// wording already used elsewhere on this page.
export function timeAgo(date) {
  const diffSec = Math.floor((Date.now() - new Date(date).getTime()) / 1000);
  if (diffSec < 60) return "just now";
  const diffMin = Math.floor(diffSec / 60);
  if (diffMin < 60) return `${diffMin}m ago`;
  const diffHr = Math.floor(diffMin / 60);
  if (diffHr < 24) return `${diffHr}h ago`;
  const diffDay = Math.floor(diffHr / 24);
  return `${diffDay}d ago`;
}

