// ── Ports of app components ──────────────────────────────────────────

// PostCard's card: the blob background with content stacked on top.
export function BlobCard({ fill, className = "", children, style }) {
  return (
    <div className={`blob-card ${className}`} style={style}>
      <svg
        className="blob-card-bg"
        viewBox="0 0 361 361"
        preserveAspectRatio="none"
        aria-hidden="true"
      >
        <path d={CARD_BLOB_PATH} fill={fill} />
      </svg>
      <div className="blob-card-body">{children}</div>
    </div>
  );
}

// ProfileImage stand-in: the app shows a photo; example buds get a plant.
export function Avatar({ emoji, bg = C.lime300, size = 32 }) {
  return (
    <span
      className="avatar"
      style={{
        width: size,
        height: size,
        background: bg,
        fontSize: size * 0.5,
      }}
      aria-hidden="true"
    >
      {emoji}
    </span>
  );
}

// Feed header bell, on its blob mask.
export function BellButton() {
  return (
    <span className="bell" aria-hidden="true">
      <svg viewBox="0 0 39 37" preserveAspectRatio="none">
        <path d={BELL_BLOB_PATH} fill={C.lime300} />
      </svg>
      <svg viewBox="0 0 24 24" width="18" height="18" className="bell-icon">
        <path
          d="M12 22a2 2 0 0 0 2-2h-4a2 2 0 0 0 2 2zm6-6V11c0-3.1-1.6-5.6-4.5-6.3V4a1.5 1.5 0 0 0-3 0v.7C7.6 5.4 6 7.9 6 11v5l-2 2v1h16v-1l-2-2z"
          fill={C.brown500}
        />
      </svg>
    </span>
  );
}

export function CategoryBadge({ category, colors }) {
  const map = {
    reading: [ICON_READING, "0 0 37 33"],
    listening: [ICON_LISTENING, "0 0 29 29"],
    watching: [ICON_WATCHING, "0 0 36 29"],
  };
  const [path, vb] = map[category];
  return (
    <span className="cat-badge" style={{ background: colors.bg }}>
      <svg width="16" height="16" viewBox={vb} aria-hidden="true">
        <path d={path} fill={colors.fg} />
      </svg>
    </span>
  );
}

// Reactions: 36px circles, overlapping, popping in. Each entry in `list`
// is an emoji name from ./emojis.js (the app's real reaction set), not a
// literal unicode character.
export function Reactions({ list, bg }) {
  return (
    <span className="reactions">
      {list.map((name, i) => (
        <span
          key={name}
          className="reaction"
          style={{ background: bg, animationDelay: `${i * 90}ms` }}
        >
          <Emoji name={name} size={20} />
        </span>
      ))}
    </span>
  );
}

// The two organic action buttons from PostCard's footer, each randomly
// flipped on mount like the app does.
export function ActionButton({ bg, flip, label, children }) {
  return (
    <button
      type="button"
      className="action-btn"
      aria-label={label}
      style={{ background: bg, transform: `scale(${flip.x}, ${flip.y})` }}
    >
      <span
        style={{
          transform: `scale(${flip.x}, ${flip.y})`,
          display: "inline-flex",
        }}
      >
        {children}
      </span>
    </button>
  );
}

