// Monochrome silhouette of the blob mark — mirrors whiteOnBrownLogo.svg,
// used for the "all buds" chip the same way the app uses it as
// allBudsIcon on a brown circle.
export function LogomarkMono({ size = 26, color = C.white200 }) {
  return (
    <svg
      viewBox="0 0 208 203"
      width={size}
      height={size * (203 / 208)}
      aria-hidden="true"
    >
      <path d={LOGO_BLOB_PATH} fill={color} />
    </svg>
  );
}

